    [Fact]
    public void Does_not_encode_again_when_nothing_changed()
    {
        using var drive = new TempFolder();
        using var work = new TempFolder();
        MakeVideo(Path.Combine(drive.Path, "clip.mp4"), 640, 360, seconds: 1);
        Process(drive, work);
        var proxy = Path.Combine(work.Path, Assert.Single(ReadManifests(work)).Derivatives[^1].Path);
        var firstWrite = new DateTime(2001, 1, 1, 0, 0, 0, DateTimeKind.Utc);
        File.SetLastWriteTimeUtc(proxy, firstWrite);

        var second = Process(drive, work);

        Assert.Equal(1, second.Skipped);
        Assert.Equal(firstWrite, File.GetLastWriteTimeUtc(proxy));
    }

